      var p = JSON.parse(raw) || {}, c = [p.login, p.email];
      for (var i = 0; i < c.length; i++) if (typeof c[i] === "string" && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c[i].trim())) return c[i].trim().toLowerCase();
      var m = raw.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);
